  VALUES 
    (754::BIGINT, 'De lo mejor para llevar ecuas en verano'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-25T00:00:00+00:00'::TIMESTAMPTZ, '543ba08b197b61ee125eedd73bbbbb274ab47847d3a9295311045d6f90b27e5a'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Demasiado facil. Los exámenes valen 95% de la nota (son tres) y eran muy sencillos. El 5% faltante es para un proyecto que también es muy facil porque las respuestas están en el folleto. Explica muy bien y te prepara bien para el examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'ab19448ecf5c12f1c3e86579ea99f3dec0a1d39f6f81f6ec60443b1f60736465'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'El curso con él es bastante relajado, incluso si es la primera vez que lo llevas, al principio te puedes asustar ya que el 95% de la nota son tres exámenes, pero son bastante sencillos, recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3726f58e8ca37f1e43732533ec42425dfe1f5154aef892a1d2720daff954a6e'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, '100% recomendado, los exámenes valen el 95% de la nota y aparte de eso son muy fáciles y no califica duro. Las clases son muy buenas y explica muy bien, hace ejemplos muy parecidos a los del examen. Si quiere llevar verano al suave llévelo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4398be74136d1c2ffda2e246efff1d50b79d167d8f61500e617e4291f7540085'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Llevar ED en verano con ese profe es lo mejor, muy ordenado, claro y respetuoso, definitivamente llevaría otra clase con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, '5c01e5e46f0308a590618bbd1bd1c056107359da8cc86297a265a2953384d8de'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Definitivamente es el mejor profesor que me ha enseñado a lo largo de mi carrera en el TEC, es muy organizado y es tiene excelentes cualidades a la hora de explicar la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, '1873a75c16b0410661c0de2b7a20bfa469b0a39c574386da6eab98bb0bc1cc07'::TEXT, ARRAY[2444]::BIGINT[]),
    (754::BIGINT, 'Explica súper bien, deja una tarea cada semana, siempre hace un repaso de la materia en cada clase, así uno no se pierde. En general, excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '0f81a5838226b80d8495bcc4eabfaf74d22dbc8731af0076d7ad8abe9bbc21a7'::TEXT, ARRAY[2444]::BIGINT[]),
    (754::BIGINT, 'Es un excelente profesor, explica con mucha paciencia y sumamente claro. Super recomendado le encanta ayudar al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '697122e26cff8f72c73ef8de4ec3a195adacf7b663cf044fc563167c163257a7'::TEXT, ARRAY[2444]::BIGINT[]),
    (754::BIGINT, '(Verano) Explica bien y el nivel del examen es el mismo que el de los ejercicios en clase, facil. Super recomendado, el curso se pasa relajado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'a6baf12e28ee2d9e97938896340f44efe69f2ab562b40c1393348f8f07fd9ac6'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '073ea39c816114df06d227533548ec2bf28f47ace780617888a03ce560b66d99'::TEXT, ARRAY[1686]::BIGINT[]),
    (754::BIGINT, 'Para verano es lo mejor, explica demasiado bien y demasiado claro, los exámenes son muy fáciles por lo que el curso se vuelve demasiado relajado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '78d8ac0be9abd2a925a6031f9fb544aa8ab2b4faa70cbdcc69a84be418936c76'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Verano. Excelentes clases, examenes super fáciles, el curso super relajado. Como vacaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '730cbe4fcd9f9fe29680d9b99f5568770813cdef19220dbba441bc4177c04e59'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Si quiere tener vacaciones y pasar ecuas, no dude en matricular con él en verano. Demasiado buen profe y super buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '90a1a1d7699d4d842a54a68a2cb41d0a120d63057c00d7c68c399900e107b4fc'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Si va a llevar ecuaciones diferenciales por primera vez en verano, no lo dude matricule con él. Las clases no se sienten tan pesadas, es muy ordenado en la pizarra y explica muy bien. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-10T00:00:00+00:00'::TIMESTAMPTZ, '2532b78a91ed0ced3aa9c9a031426f939c52c6822b30066cf6c4a3a28500fbfb'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Las clases son claras y explica de una manera simple, por lo que es muy fácil entender. Ademas, vacila con el grupo y los exámenes son accesibles :) Los ejemplos que utliza son aplicados a la realidad, por lo que se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'a815212a595d62f7378d1073f56aacb905db24b6de8aa458eabc1d3e7d09d2a2'::TEXT, ARRAY[2444]::BIGINT[]),
    (754::BIGINT, 'Excelente profesor con mucha vocación y pedagogía para enseñar, sin duda el mejor profesor de matemática que he tenido hasta la fecha. Una leyenda viva de la UNA y UCR, especialmente por haber pasado siempre con 100 cada curso que llevo cuando fue estudiante. Uno de los pocos Doctores del Tec.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-08-09T00:00:00+00:00'::TIMESTAMPTZ, '210b75eb3ae745c00ff2a147fbadbf496ba8c9cc08c7999c3978e3522fbcc356'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ea07fa6d6e38b5583e130e422957302947d6746ee42843e8e1ba020b715e0dc9'::TEXT, ARRAY[935]::BIGINT[]),
    (754::BIGINT, 'Explica de una manera sencilla y muy clara'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '86a09ac25e60d7b41ca1711ed11aa086008abeaf1d30298c5503a6c9e8270473'::TEXT, ARRAY[2444]::BIGINT[]),
